import {BatchPolishView} from '../../src/features/polish-batch.ts';
export function createBatchFixture(){let source='source1',sections={原理:'原理 $x=1$',方法:'原方法',结论:'原结论',思考题:'题目'},calls:string[]=[],imports=0,active=0,maxActive=0,fail='方法',pending=false,late:((v:{text:string})=>void)|undefined,last:unknown=null;const view=new BatchPolishView({context:()=>({source,sections}),request:async(section,original,_instruction,signal)=>{calls.push(section);active++;maxActive=Math.max(maxActive,active);try{if(pending)return await new Promise<{text:string}>(r=>late=r);if(section===fail)throw Error('模拟章节失败');return {text:'润色 '+original};}finally{active--; }},import:async(current,entries)=>{if(current!==source)throw Error('source mismatch');imports++;last=entries;},changed:()=>{}});const mount=()=>view.mount(document.querySelector<HTMLElement>('#batch-host')!);mount();return {state:()=>({calls,imports,maxActive,busy:view.isBusy,last}),fail:(v:string)=>fail=v,pending:()=>pending=true,late:()=>{pending=false;late?.({text:'旧响应'});},change:()=>source+='changed',original:()=>sections={...sections,原理:'已修改原文'},reopen:mount,leave:()=>view.leave()};}
